export function useMemo(name: string, options?: { enabled?: boolean }) {
  return useQuery({
    queryKey: memoKeys.detail(name),
    queryFn: async () => {
      const memo = await memoServiceClient.getMemo({ name });
      return memo;
    },
    enabled: options?.enabled ?? true,
    staleTime: 1000 * 10, // 10 seconds - reduced to prevent stale data in collaborative editing
  });
}

export const useLocation = (initialLocation?: Location) => {
  const [locationInitialized, setLocationInitialized] = useState(false);
  const locationInitializedRef = useRef(locationInitialized);
  locationInitializedRef.current = locationInitialized;

  const [state, setState] = useState<LocationState>({
    placeholder: initialLocation?.placeholder || "",
    position: initialLocation ? { lat: initialLocation.latitude, lng: initialLocation.longitude } : undefined,
    latInput: initialLocation ? String(initialLocation.latitude) : "",
    lngInput: initialLocation ? String(initialLocation.longitude) : "",
  });

  // Ref to latest state so getLocation can be stable without closing over state.
  const stateRef = useRef(state);
  stateRef.current = state;

  const updatePosition = useCallback((position?: MapPoint) => {
    setState((prev) => ({
      ...prev,
      position,
      latInput: position ? String(position.lat) : "",
      lngInput: position ? String(position.lng) : "",
    }));
  }, []);

  // Stable ??? reads locationInitialized via ref to avoid recreating on every change.
  const handlePositionChange = useCallback(
    (position: MapPoint) => {
      if (!locationInitializedRef.current) setLocationInitialized(true);
      updatePosition(position);
    },
    [updatePosition],
  );

  // Stable ??? merges coordinate update into a single functional setState, avoiding closure over state.position.
  const updateCoordinate = useCallback((type: "lat" | "lng", value: string) => {
    const num = parseFloat(value);
    const isValid = type === "lat" ? !isNaN(num) && num >= -90 && num <= 90 : !isNaN(num) && num >= -180 && num <= 180;
    setState((prev) => {
      const next = { ...prev, [type === "lat" ? "latInput" : "lngInput"]: value };
      if (isValid && prev.position) {
        const newPos = type === "lat" ? { lat: num, lng: prev.position.lng } : { lat: prev.position.lat, lng: num };
        return { ...next, position: newPos, latInput: String(newPos.lat), lngInput: String(newPos.lng) };
      }
      return next;
    });
  }, []);

  // Stable reference ??? uses functional setState, no closure deps.
  const setPlaceholder = useCallback((placeholder: string) => {
    setState((prev) => ({ ...prev, placeholder }));
  }, []);

  const reset = useCallback(() => {
    setState({
      placeholder: "",
      position: undefined,
      latInput: "",
      lngInput: "",
    });
    setLocationInitialized(false);
  }, []);

  // Stable ??? reads latest state via ref, no closure over state.
  const getLocation = useCallback((): Location | undefined => {
    const { position, placeholder } = stateRef.current;
    if (!position || !placeholder.trim()) {
      return undefined;
    }
    return create(LocationSchema, {
      latitude: position.lat,
      longitude: position.lng,
      placeholder,
    });
  }, []);

  return useMemo(
    () => ({ state, locationInitialized, handlePositionChange, updateCoordinate, setPlaceholder, reset, getLocation }),
    [state, locationInitialized, handlePositionChange, updateCoordinate, setPlaceholder, reset, getLocation],
  );
};

export const getRelationMemo = (relation: MemoRelation, direction: RelationDirection) => {
  return direction === "referencing" ? relation.relatedMemo : relation.memo;
};

export const useMemoFilters = (options: UseMemoFiltersOptions = {}): string | undefined => {
  const { creatorName, includeShortcuts = false, includePinned = false, visibilities } = options;

  const { shortcuts } = useAuth();
  const { filters, shortcut: currentShortcut } = useMemoFilterContext();

  // Get selected shortcut if needed
  const selectedShortcut = useMemo(() => {
    if (!includeShortcuts) return undefined;
    return shortcuts.find((shortcut) => getShortcutId(shortcut.name) === currentShortcut);
  }, [includeShortcuts, currentShortcut, shortcuts]);

  // Build filter
  return useMemo(() => {
    const conditions: string[] = [];

    // Add creator filter if provided
    if (creatorName) {
      const creatorFilter = buildMemoCreatorFilter(creatorName);
      if (creatorFilter) {
        conditions.push(creatorFilter);
      }
    }

    // Add shortcut filter if enabled and selected
    if (includeShortcuts && selectedShortcut?.filter) {
      conditions.push(selectedShortcut.filter);
    }

    // Add active filters from context
    for (const filter of filters) {
      if (filter.factor === "contentSearch") {
        conditions.push(`content.contains(${escapeFilterValue(filter.value)})`);
      } else if (filter.factor === "tagSearch") {
        conditions.push(`tag in [${escapeFilterValue(filter.value)}]`);
      } else if (filter.factor === "pinned") {
        if (includePinned) {
          conditions.push(`pinned`);
        }
      } else if (filter.factor === "property.hasLink") {
        conditions.push(`has_link`);
      } else if (filter.factor === "property.hasTaskList") {
        conditions.push(`has_task_list`);
      } else if (filter.factor === "property.hasCode") {
        conditions.push(`has_code`);
      } else if (filter.factor === "displayTime") {
        const filterDate = new Date(filter.value);
        const filterUtcTimestamp = filterDate.getTime() + filterDate.getTimezoneOffset() * 60 * 1000;
        const startTimestamp = Math.floor(filterUtcTimestamp / 1000);
        const endTimestamp = startTimestamp + 60 * 60 * 24;

        conditions.push(`created_ts >= timestamp(${startTimestamp}) && created_ts < timestamp(${endTimestamp})`);
      }
    }

    // Add visibility filter if specified
    if (visibilities && visibilities.length > 0) {
      const visibilityValues = visibilities.map((v) => `"${getVisibilityName(v)}"`).join(", ");
      conditions.push(`visibility in [${visibilityValues}]`);
    }

    return conditions.length > 0 ? conditions.join(" && ") : undefined;
  }, [creatorName, includeShortcuts, includePinned, visibilities, selectedShortcut, filters]);
};

export function useUpdateMemo() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ update, updateMask }: { update: Partial<Memo>; updateMask: string[] }) => {
      const memo = await memoServiceClient.updateMemo({
        memo: create(MemoSchema, update as Record<string, unknown>),
        updateMask: create(FieldMaskSchema, { paths: updateMask }),
      });
      return memo;
    },
    onMutate: async ({ update }) => {
      if (!update.name) {
        return { previousMemo: undefined };
      }

      // Cancel outgoing refetches to prevent race conditions
      await queryClient.cancelQueries({ queryKey: memoKeys.all });

      // Snapshot previous value for rollback on error
      const previousMemo =
        queryClient.getQueryData<Memo>(memoKeys.detail(update.name)) || findMemoInCollectionQueries(queryClient, update.name);
      const memoPatch: MemoPatch = { ...update, name: update.name };

      // Optimistically update the cache
      if (previousMemo) {
        queryClient.setQueryData(memoKeys.detail(update.name), { ...previousMemo, ...memoPatch });
      }
      patchMemoInCollectionQueries(queryClient, memoPatch);

      return { previousMemo };
    },
    onError: (_err, { update }, context) => {
      // Rollback on error
      if (context?.previousMemo && update.name) {
        queryClient.setQueryData(memoKeys.detail(update.name), context.previousMemo);
        patchMemoInCollectionQueries(queryClient, context.previousMemo);
      } else {
        queryClient.invalidateQueries({ queryKey: memoKeys.all });
      }
    },
    onSuccess: (updatedMemo) => {
      // Update cache with server response
      queryClient.setQueryData(memoKeys.detail(updatedMemo.name), updatedMemo);
      patchMemoInCollectionQueries(queryClient, updatedMemo);
      // Invalidate lists to refresh
      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
      if (updatedMemo.parent) {
        queryClient.invalidateQueries({ queryKey: memoKeys.comments(updatedMemo.parent) });
      }
      // Invalidate user stats
      queryClient.invalidateQueries({ queryKey: userKeys.stats() });
    },
  });
}

export const useMemoSorting = (options: UseMemoSortingOptions = {}): UseMemoSortingResult => {
  const { pinnedFirst = false, state = State.NORMAL } = options;
  const { orderByTimeAsc, timeBasis } = useView();

  // Generate orderBy string for API
  const orderBy = useMemo(() => {
    const timeOrder = orderByTimeAsc ? `${timeBasis} asc` : `${timeBasis} desc`;
    return pinnedFirst ? `pinned desc, ${timeOrder}` : timeOrder;
  }, [pinnedFirst, orderByTimeAsc, timeBasis]);

  // Generate listSort function for client-side sorting
  const listSort = useMemo(() => {
    return (memos: Memo[]): Memo[] => {
      return memos
        .filter((memo) => memo.state === state)
        .sort((a, b) => {
          // First, sort by pinned status if enabled
          if (pinnedFirst && a.pinned !== b.pinned) {
            return b.pinned ? 1 : -1;
          }

          // Then sort by the selected time field.
          const aTime = getMemoSortTime(a, timeBasis);
          const bTime = getMemoSortTime(b, timeBasis);
          return orderByTimeAsc ? dayjs(aTime).unix() - dayjs(bTime).unix() : dayjs(bTime).unix() - dayjs(aTime).unix();
        });
    };
  }, [pinnedFirst, state, orderByTimeAsc, timeBasis]);

  return { listSort, orderBy };
};

export const extractMemoIdFromName = (name: string) => {
  return name.split(memoNamePrefix).pop() || "";
};

export const useResolvedRelationMemos = (relations: MemoRelation[]) => {
  const [resolvedMemos, setResolvedMemos] = useState<Record<string, MemoRelation_Memo>>({});

  const missingMemoNames = useMemo(() => {
    const names = new Set<string>();

    for (const relation of relations) {
      for (const memo of [relation.memo, relation.relatedMemo]) {
        if (memo?.name && !memo.snippet && !resolvedMemos[memo.name]) {
          names.add(memo.name);
        }
      }
    }

    return [...names];
  }, [relations, resolvedMemos]);

  useEffect(() => {
    if (missingMemoNames.length === 0) {
      return;
    }

    let cancelled = false;

    void (async () => {
      try {
        const memos = await Promise.all(
          missingMemoNames.map(async (name) => {
            const memo = await memoServiceClient.getMemo({ name });
            return create(MemoRelation_MemoSchema, { name: memo.name, snippet: memo.snippet });
          }),
        );

        if (cancelled) {
          return;
        }

        setResolvedMemos((prev) => {
          const next = { ...prev };
          for (const memo of memos) {
            next[memo.name] = memo;
          }
          return next;
        });
      } catch {
        // Keep existing relation data when snippet hydration fails.
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [missingMemoNames]);

  return resolvedMemos;
};

function patchMemoInCollectionQueries(queryClient: ReturnType<typeof useQueryClient>, update: MemoPatch) {
  queryClient.setQueriesData<MemoCollectionQueryData>({ queryKey: memoKeys.all }, (data) => patchMemoListQueryData(data, update));
}

export const buildMemoCreatorFilter = (name: string) => {
  if (!name) {
    return undefined;
  }
  const normalizedName = name.startsWith(userNamePrefix) ? name : `${userNamePrefix}${name}`;
  return `creator == ${JSON.stringify(normalizedName)}`;
};

async save(
  state: EditorState,
  options: {
    memoName?: string;
    parentMemoName?: string;
  },
): Promise<{ memoName: string; hasChanges: boolean }> {
  // 1. Upload local files first
  const newAttachments = await uploadService.uploadFiles(state.localFiles);
  const allAttachments = [...state.metadata.attachments, ...newAttachments];

  // 2. Update existing memo
  if (options.memoName) {
    const prevMemo = await memoServiceClient.getMemo({ name: options.memoName });
    const { mask, patch } = buildUpdateMask(prevMemo, state, allAttachments);

    if (mask.size === 0) {
      return { memoName: prevMemo.name, hasChanges: false };
    }

    const memo = await memoServiceClient.updateMemo({
      memo: create(MemoSchema, patch as Record<string, unknown>),
      updateMask: create(FieldMaskSchema, { paths: Array.from(mask) }),
    });
    return { memoName: memo.name, hasChanges: true };
  }

  // 3. Create new memo or comment
  const memoData = create(MemoSchema, {
    content: state.content,
    visibility: state.metadata.visibility,
    attachments: toAttachmentReferences(allAttachments),
    relations: state.metadata.relations,
    location: state.metadata.location,
    createTime: state.timestamps.createTime ? timestampFromDate(state.timestamps.createTime) : undefined,
    updateTime: state.timestamps.updateTime ? timestampFromDate(state.timestamps.updateTime) : undefined,
  });

  const memo = options.parentMemoName
    ? await memoServiceClient.createMemoComment({
        name: options.parentMemoName,
        comment: memoData,
      })
    : await memoServiceClient.createMemo({ memo: memoData });

  return { memoName: memo.name, hasChanges: true };
},

export const getRelationBuckets = (relations: MemoRelation[], currentMemoName?: string) => {
  return relations.reduce(
    (groups, relation) => {
      if (!isReferenceRelation(relation)) {
        return groups;
      }

      if (relation.memo?.name === currentMemoName && relation.relatedMemo?.name !== currentMemoName) {
        groups.referencing.push(relation);
      } else if (relation.memo?.name !== currentMemoName && relation.relatedMemo?.name === currentMemoName) {
        groups.referenced.push(relation);
      }

      return groups;
    },
    {
      referencing: [] as MemoRelation[],
      referenced: [] as MemoRelation[],
    },
  );
};

const handleReactionClick = async (reactionType: string) => {
  if (!currentUser) return;

  try {
    if (hasReacted(reactionType)) {
      const reactions = memo.reactions.filter(
        (reaction) => reaction.reactionType === reactionType && reaction.creator === currentUser.name,
      );
      await Promise.all(reactions.map((reaction) => memoServiceClient.deleteMemoReaction({ name: reaction.name })));
    } else {
      await memoServiceClient.upsertMemoReaction({
        name: memo.name,
        reaction: { contentId: memo.name, reactionType },
      });
    }
    // Refetch the memo to get updated reactions and invalidate cache
    const updatedMemo = await memoServiceClient.getMemo({ name: memo.name });
    queryClient.setQueryData(memoKeys.detail(memo.name), updatedMemo);
    queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
    // If this memo is a comment, refresh the parent's comments list so the comment's reactions update in the UI
    if (memo.parent) {
      queryClient.invalidateQueries({ queryKey: memoKeys.comments(memo.parent) });
    }
  } catch {
    // skip error
  }
  onComplete?.();
};

export async function getRequestToken(): Promise<string | null> {
  let token = getAccessToken();
  if (!token) {
    if (!hasStoredToken()) return null;
    try {
      token = await refreshAndGetAccessToken();
    } catch {
      return null;
    }
    return token;
  }

  // Preflight refresh: avoid sending requests with expired access tokens.
  // This is especially important for public endpoints (e.g. ListMemos), where
  // an expired token could otherwise be treated as anonymous and return
  // guest-scoped data before the reactive 401 refresh path runs.
  if (isTokenExpired(REQUEST_TOKEN_EXPIRY_BUFFER_MS)) {
    try {
      token = await refreshAndGetAccessToken();
    } catch {
      // Keep existing reactive 401 flow as fallback.
      // Protected methods still trigger refresh/redirect in the catch block below.
    }
  }

  return token;
}

function isMemoListResponse(data: unknown): data is ListMemosResponse {
  return typeof data === "object" && data !== null && Array.isArray((data as { memos?: unknown }).memos);
}

function isInfiniteMemoListData(data: unknown): data is InfiniteData<ListMemosResponse> {
  return typeof data === "object" && data !== null && Array.isArray((data as { pages?: unknown }).pages);
}

export function useInfiniteMemos(request: Partial<ListMemosRequest> = {}, options?: { enabled?: boolean }) {
  return useInfiniteQuery({
    queryKey: memoKeys.list(request),
    queryFn: async ({ pageParam }) => {
      const response = await memoServiceClient.listMemos(
        create(ListMemosRequestSchema, {
          ...request,
          pageToken: pageParam || "",
        } as Record<string, unknown>),
      );
      return response;
    },
    initialPageParam: "",
    getNextPageParam: (lastPage) => lastPage.nextPageToken || undefined,
    staleTime: 1000 * 60,
    gcTime: 1000 * 60 * 5,
    enabled: options?.enabled ?? true,
  });
}

export const useWeekdayLabels = () => {
  const t = useTranslate();
  return useMemo(
    () => [
      t("common.days.sun"),
      t("common.days.mon"),
      t("common.days.tue"),
      t("common.days.wed"),
      t("common.days.thu"),
      t("common.days.fri"),
      t("common.days.sat"),
    ],
    [t],
  );
};

export const useCalendarMatrix = ({
  month,
  data,
  weekDays,
  weekStartDayOffset,
  today,
  selectedDate,
}: UseCalendarMatrixParams): CalendarMatrixResult => {
  return useMemo(() => {
    // Determine the start of the month and its formatted key (YYYY-MM)
    const monthStart = dayjs(month).startOf("month");
    const monthKey = monthStart.format("YYYY-MM");

    // Rotate week labels based on the user's preferred start of the week
    const rotatedWeekDays = weekDays.slice(weekStartDayOffset).concat(weekDays.slice(0, weekStartDayOffset));

    // Calculate the start and end dates for the calendar grid to ensure full weeks
    const { calendarStart, dayCount } = calculateCalendarBoundaries(monthStart, weekStartDayOffset);

    const weeks: CalendarMatrixResult["weeks"] = [];

    // Iterate through each day in the calendar grid
    for (let index = 0; index < dayCount; index += 1) {
      const current = calendarStart.add(index, "day");
      const weekIndex = Math.floor(index / DAYS_IN_WEEK);

      if (!weeks[weekIndex]) {
        weeks[weekIndex] = { days: [] };
      }

      // Create the day cell object with data and status flags
      const dayCell = createCalendarDayCell(current, monthKey, data, today, selectedDate);
      weeks[weekIndex].days.push(dayCell);
    }

    return {
      weeks,
      weekDays: rotatedWeekDays,
    };
  }, [month, data, weekDays, weekStartDayOffset, today, selectedDate]);
};

export const getTooltipText = (count: number, date: string, t: TranslateFunction, timeBasis: MemoTimeBasis = "create_time"): string => {
  if (count === 0) {
    return date;
  }

  const key = timeBasis === "update_time" ? "memo.count-memos-updated-in-date" : "memo.count-memos-in-date";
  return t(key, {
    count,
    memos: count === 1 ? t("common.memo") : t("common.memos"),
    date,
  }).toLowerCase();
};

export const useMemoActionHandlers = ({ memo, onEdit, setDeleteDialogOpen }: UseMemoActionHandlersOptions) => {
  const t = useTranslate();
  const location = useLocation();
  const navigateTo = useNavigateTo();
  const queryClient = useQueryClient();
  const { profile } = useInstance();
  const { mutateAsync: updateMemo } = useUpdateMemo();
  const { mutateAsync: deleteMemo } = useDeleteMemo();
  const isInMemoDetailPage = location.pathname.startsWith(`/${memo.name}`);

  const memoUpdatedCallback = useCallback(() => {
    // Invalidate user stats to trigger refetch
    queryClient.invalidateQueries({ queryKey: userKeys.stats() });
  }, [queryClient]);

  const updateMemoContent = useCallback(
    async (nextContent: string, context: string) => {
      if (nextContent === memo.content) {
        return;
      }

      try {
        await updateMemo({
          update: {
            name: memo.name,
            content: nextContent,
          },
          updateMask: ["content", "update_time"],
        });
        toast.success(t("memo.task-actions.updated"));
      } catch (error: unknown) {
        handleError(error, toast.error, {
          context,
          fallbackMessage: "An error occurred",
        });
      }
    },
    [memo.content, memo.name, t, updateMemo],
  );

  const handleTogglePinMemoBtnClick = useCallback(async () => {
    try {
      await updateMemo({
        update: {
          name: memo.name,
          pinned: !memo.pinned,
        },
        updateMask: ["pinned"],
      });
    } catch {
      // do nothing
    }
  }, [memo.name, memo.pinned, updateMemo]);

  const handleEditMemoClick = useCallback(() => {
    onEdit?.();
  }, [onEdit]);

  const handleToggleMemoStatusClick = useCallback(async () => {
    const isArchiving = memo.state !== State.ARCHIVED;
    const state = memo.state === State.ARCHIVED ? State.NORMAL : State.ARCHIVED;
    const message = memo.state === State.ARCHIVED ? t("message.restored-successfully") : t("message.archived-successfully");

    try {
      await updateMemo({
        update: {
          name: memo.name,
          state,
        },
        updateMask: ["state"],
      });
      toast.success(message);
    } catch (error: unknown) {
      handleError(error, toast.error, {
        context: `${isArchiving ? "Archive" : "Restore"} memo`,
        fallbackMessage: "An error occurred",
      });
      return;
    }

    if (isInMemoDetailPage) {
      navigateTo(memo.state === State.ARCHIVED ? ROUTES.HOME : ROUTES.ARCHIVED);
    }
    memoUpdatedCallback();
  }, [memo.name, memo.state, t, isInMemoDetailPage, navigateTo, memoUpdatedCallback, updateMemo]);

  const handleCopyLink = useCallback(() => {
    let host = profile.instanceUrl;
    if (host === "") {
      host = window.location.origin;
    }
    copy(`${host}/${memo.name}`);
    toast.success(t("message.succeed-copy-link"));
  }, [memo.name, t, profile.instanceUrl]);

  const handleCopyContent = useCallback(() => {
    copy(memo.content);
    toast.success(t("message.succeed-copy-content"));
  }, [memo.content, t]);

  const handleCheckAllTaskListItemsClick = useCallback(async () => {
    await updateMemoContent(checkAllTasks(memo.content), "Check memo task list items");
  }, [memo.content, updateMemoContent]);

  const handleUncheckAllTaskListItemsClick = useCallback(async () => {
    await updateMemoContent(uncheckAllTasks(memo.content), "Uncheck memo task list items");
  }, [memo.content, updateMemoContent]);

  const handleDeleteMemoClick = useCallback(() => {
    setDeleteDialogOpen(true);
  }, [setDeleteDialogOpen]);

  const confirmDeleteMemo = useCallback(async () => {
    try {
      await deleteMemo(memo.name);
    } catch (error: unknown) {
      handleError(error, toast.error, { context: "Delete memo", fallbackMessage: "An error occurred" });
      return;
    }
    toast.success(t("message.deleted-successfully"));
    if (memo.parent) {
      queryClient.invalidateQueries({ queryKey: memoKeys.comments(memo.parent) });
    }
    if (isInMemoDetailPage) {
      navigateTo(ROUTES.HOME);
    }
    memoUpdatedCallback();
  }, [memo.name, memo.parent, t, isInMemoDetailPage, navigateTo, memoUpdatedCallback, deleteMemo, queryClient]);

  return {
    handleTogglePinMemoBtnClick,
    handleEditMemoClick,
    handleToggleMemoStatusClick,
    handleCopyLink,
    handleCopyContent,
    handleCheckAllTaskListItemsClick,
    handleUncheckAllTaskListItemsClick,
    handleDeleteMemoClick,
    confirmDeleteMemo,
  };
};

export const buildMemoShareImageFileName = (memoName: string) => {
  const suffix = memoName.split("/").pop() || "memo";
  return `memo-${suffix}.png`;
};

export const getMemoSharePreviewWidth = (cardWidth: number) => {
  const viewportWidth =
    typeof window === "undefined" ? MEMO_SHARE_IMAGE_CONFIG.maxWidth : window.innerWidth - MEMO_SHARE_IMAGE_CONFIG.viewportMargin;
  const baseWidth = cardWidth || viewportWidth;

  return clamp(
    Math.round(baseWidth * MEMO_SHARE_IMAGE_CONFIG.previewScale),
    MEMO_SHARE_IMAGE_CONFIG.minWidth,
    MEMO_SHARE_IMAGE_CONFIG.maxWidth,
  );
};

export const getMemoShareDialogWidth = (previewWidth: number) => {
  const viewportWidth =
    typeof window === "undefined" ? previewWidth + MEMO_SHARE_IMAGE_CONFIG.dialogExtraWidth : window.innerWidth - WINDOW_HORIZONTAL_MARGIN;
  return Math.min(previewWidth + MEMO_SHARE_IMAGE_CONFIG.dialogExtraWidth, viewportWidth);
};

export const getMemoShareRenderWidth = (previewWidth: number, dialogWidth: number) => {
  const maxRenderWidth = Math.max(MEMO_SHARE_IMAGE_CONFIG.minWidth, dialogWidth - PREVIEW_HORIZONTAL_PADDING_IN_DIALOG);
  return clamp(previewWidth + PREVIEW_WIDTH_BOOST_IN_DIALOG, MEMO_SHARE_IMAGE_CONFIG.minWidth, maxRenderWidth);
};

export const createMemoShareImageBlob = async (node: HTMLElement) => {
  await waitForPreviewAssets(node);

  const rect = node.getBoundingClientRect();
  const width = Math.ceil(rect.width || node.offsetWidth || node.clientWidth);
  const height = Math.ceil(rect.height || node.offsetHeight || node.clientHeight);

  const blob = await toBlob(node, {
    cacheBust: true,
    height,
    pixelRatio: Math.max(2, Math.min(window.devicePixelRatio || 1, 3)),
    width,
    filter: (currentNode) => {
      if (!(currentNode instanceof HTMLElement)) {
        return true;
      }

      if (currentNode instanceof HTMLImageElement) {
        return isExportableImageUrl(currentNode.currentSrc || currentNode.src);
      }

      return !(currentNode instanceof HTMLVideoElement);
    },
  });

  if (!blob) {
    throw new Error("Failed to render image");
  }

  return blob;
};

export const buildMemoShareImagePreviewModel = ({
  memo,
  creator,
  fallbackDisplayName,
  locale,
}: BuildMemoShareImagePreviewModelOptions): MemoShareImagePreviewModel => {
  const displayName = creator?.displayName || creator?.username || fallbackDisplayName;
  const avatarUrl = getMemoSharePreviewAvatarUrl(creator?.avatarUrl);
  const displayTime = memo.createTime ? timestampDate(memo.createTime) : undefined;
  const formattedDisplayTime = displayTime?.toLocaleString(locale, {
    dateStyle: "medium",
    timeStyle: "short",
  });

  const attachmentGroups = separateAttachments(memo.attachments);
  const visualItems = buildAttachmentVisualItems(attachmentGroups.visual);
  const attachmentCount = countLogicalAttachmentItems(memo.attachments);
  const nonVisualAttachmentCount = Math.max(attachmentCount - visualItems.length, 0);
  const footerBadges: MemoShareImageFooterBadge[] =
    nonVisualAttachmentCount > 0 ? [{ type: "attachment-summary", count: attachmentCount }] : [];

  return {
    displayName,
    avatarUrl,
    formattedDisplayTime,
    visualItems,
    footerBadges,
  };
};

